referenceSolutionTemplate:
import java.util.Scanner;

public class Main {
    public static void rollCall(int n) {
        for (int i = 1; i <= n; i++) {
            System.out.println("第 " + i + " 只：{word}");
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        rollCall(n);
    }
}
